window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9c9ae067325cbdcb"]={"versions": [{"id": "FIG-9c9ae067325cbdcb", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine) der AUTOSAR Runtime Environment (RTE). Das Diagramm modelliert den Lebenszyklus und Aktivierungsmechanismus einer AUTOSAR Runnable Entity (ausdrücklich ausgenommen Server-Runnables) und gliedert sich über eine gestrichelte Trennlinie in zwei parallele, orthogonale Teilzustandsräume: den Hauptausführungszustand <code>[main]</code> und den Aktivierungs-/Entprellungszustand <code>[activation]</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei orthogonale Regionen mit folgenden Zuständen und Pseudozuständen:</p>\n<ul class=\"fig-list\">\n<li>Region <code>[main]</code>:</li>\n<li>Start-Pseudozustand (Initial State)</li>\n<li>Einfache Zustände: <code>suspended</code>, <code>to be started</code></li>\n<li>Zusammengesetzter Zustand (Composite State): <code>started</code> mit eigenem Start-Pseudozustand und den Unterzuständen <code>running</code>, <code>waiting</code> sowie <code>preempted</code></li>\n<li>Zustandskonzept: <code>ready</code> (gestrichelt umrandet, umfasst logisch <code>to be started</code> und <code>preempted</code>)</li>\n<li>Region <code>[activation]</code>:</li>\n<li>Start-Pseudozustand (Initial State)</li>\n<li>Zustände: <code>not activated</code>, <code>debounce activation</code>, <code>activated</code></li>\n<li>Schnittstellen und interne Variablen/Timer:</li>\n<li>Lokaler Zähler/Timer: <code>runnable debounce timer</code></li>\n<li>Konfigurationsparameter: <code>minimum start interval</code> (bzw. Initialisierungswert <code>minimum start intervall</code>)</li>\n<li>Ereignisse/Trigger und Guards: <code>activate</code>, <code>start</code>, <code>terminate</code>, <code>wait</code>, <code>release</code>, <code>preempt</code>, <code>resume</code>, <code>[activated]</code>, <code>[runnable debounce timer &gt;= minimum start interval]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Region <code>[activation]</code> (Aktivierungslogik & Entprellung):</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Aus dem Start-Pseudozustand erfolgt der Übergang nach <code>not activated</code> unter der Aktion <code>/runnable debounce timer = minimum start intervall</code>.</li>\n<li>Durch das Ereignis <code>activate</code> wechselt der Zustand von <code>not activated</code> nach <code>debounce activation</code>.</li>\n<li>Bei Erfüllung der Guard-Bedingung <code>[runnable debounce timer &gt;= minimum start interval]</code> geht das System von <code>debounce activation</code> in <code>activated</code> über.</li>\n<li>Mit dem Ereignis <code>start</code> wechselt der Zustand zurück nach <code>not activated</code>, wobei der Entprelltimer mit der Aktion <code>/ runnable debounce timer = 0</code> zurückgesetzt wird.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Region <code>[main]</code> (Ausführungslebenszyklus):</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Aus dem Start-Pseudozustand wird initial <code>suspended</code> eingenommen.</li>\n<li>Bei erfüllter Bedingung <code>[activated]</code> wechselt die Runnable nach <code>to be started</code> (Teil des logischen <code>ready</code>-Zustands).</li>\n<li>Das Ereignis <code>start</code> überführt die Runnable in den Unterzustand <code>preempted</code> innerhalb des Superzustands <code>started</code>.</li>\n<li>Innerhalb von <code>started</code> verzweigt der interne Initial-Pseudozustand direkt nach <code>running</code>.</li>\n<li>Im laufenden Betrieb wechselt die Runnable über <code>wait</code> nach <code>waiting</code> und kehrt über <code>release</code> nach <code>preempted</code> zurück; bei Verdrängung wechselt sie über <code>preempt</code> von <code>running</code> nach <code>preempted</code> und kehrt über <code>resume</code> nach <code>running</code> zurück.</li>\n<li>Aus dem Superzustand <code>started</code> führt das Ereignis <code>terminate</code> zurück in den Zustand <code>suspended</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das normative Zustandsverhalten einer Client-/Standard-Runnable-Entity gegenüber der RTE. Der <code>runnable debounce timer</code> ist als ansteigender lokaler Timer ein rein normatives Spezifikationskonzept zur formalen Beschreibung des Mindeststartintervalls (<code>minimum start interval</code>) und kein zwingender Bestandteil einer tatsächlichen Implementierung. RTE-Generatoren und OS-Scheduler müssen sicherstellen, dass Aktivierungsereignisse (<code>activate</code>) das konfigurierte Mindestintervall einhalten, bevor die Runnable erneut gestartet wird (<code>start</code>). Server-Runnables unterliegen gesonderten Ausführungsregeln und sind von dieser Zustandsmaschine ausgenommen.</p>"}, {"id": "FIG-f3c0d3883ed626c1", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine) der AUTOSAR Runtime Environment (RTE). Das Diagramm modelliert den Lebenszyklus und Aktivierungsmechanismus einer AUTOSAR Runnable Entity (ausdrücklich ausgenommen Server-Runnables) und gliedert sich über eine gestrichelte Trennlinie in zwei parallele, orthogonale Teilzustandsräume: den Hauptausführungszustand <code>[main]</code> und den Aktivierungs-/Entprellungszustand <code>[activation]</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei orthogonale Regionen mit folgenden Zuständen und Pseudozuständen:</p>\n<ul class=\"fig-list\">\n<li>Region <code>[main]</code>:</li>\n<li>Start-Pseudozustand (Initial State)</li>\n<li>Einfache Zustände: <code>suspended</code>, <code>to be started</code></li>\n<li>Zusammengesetzter Zustand (Composite State): <code>started</code> mit eigenem Start-Pseudozustand und den Unterzuständen <code>running</code>, <code>waiting</code> sowie <code>preempted</code></li>\n<li>Zustandskonzept: <code>ready</code> (gestrichelt umrandet, umfasst logisch <code>to be started</code> und <code>preempted</code>)</li>\n<li>Region <code>[activation]</code>:</li>\n<li>Start-Pseudozustand (Initial State)</li>\n<li>Zustände: <code>not activated</code>, <code>debounce activation</code>, <code>activated</code></li>\n<li>Schnittstellen und interne Variablen/Timer:</li>\n<li>Lokaler Zähler/Timer: <code>runnable debounce timer</code></li>\n<li>Konfigurationsparameter: <code>minimum start interval</code> (bzw. Initialisierungswert <code>minimum start intervall</code>)</li>\n<li>Ereignisse/Trigger und Guards: <code>activate</code>, <code>start</code>, <code>terminate</code>, <code>wait</code>, <code>release</code>, <code>preempt</code>, <code>resume</code>, <code>[activated]</code>, <code>[runnable debounce timer &gt;= minimum start interval]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Region <code>[activation]</code> (Aktivierungslogik & Entprellung):</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Aus dem Start-Pseudozustand erfolgt der Übergang nach <code>not activated</code> unter der Aktion <code>/runnable debounce timer = minimum start intervall</code>.</li>\n<li>Durch das Ereignis <code>activate</code> wechselt der Zustand von <code>not activated</code> nach <code>debounce activation</code>.</li>\n<li>Bei Erfüllung der Guard-Bedingung <code>[runnable debounce timer &gt;= minimum start interval]</code> geht das System von <code>debounce activation</code> in <code>activated</code> über.</li>\n<li>Mit dem Ereignis <code>start</code> wechselt der Zustand zurück nach <code>not activated</code>, wobei der Entprelltimer mit der Aktion <code>/ runnable debounce timer = 0</code> zurückgesetzt wird.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Region <code>[main]</code> (Ausführungslebenszyklus):</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Aus dem Start-Pseudozustand wird initial <code>suspended</code> eingenommen.</li>\n<li>Bei erfüllter Bedingung <code>[activated]</code> wechselt die Runnable nach <code>to be started</code> (Teil des logischen <code>ready</code>-Zustands).</li>\n<li>Das Ereignis <code>start</code> überführt die Runnable in den Unterzustand <code>preempted</code> innerhalb des Superzustands <code>started</code>.</li>\n<li>Innerhalb von <code>started</code> verzweigt der interne Initial-Pseudozustand direkt nach <code>running</code>.</li>\n<li>Im laufenden Betrieb wechselt die Runnable über <code>wait</code> nach <code>waiting</code> und kehrt über <code>release</code> nach <code>preempted</code> zurück; bei Verdrängung wechselt sie über <code>preempt</code> von <code>running</code> nach <code>preempted</code> und kehrt über <code>resume</code> nach <code>running</code> zurück.</li>\n<li>Aus dem Superzustand <code>started</code> führt das Ereignis <code>terminate</code> zurück in den Zustand <code>suspended</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das normative Zustandsverhalten einer Client-/Standard-Runnable-Entity gegenüber der RTE. Der <code>runnable debounce timer</code> ist als ansteigender lokaler Timer ein rein normatives Spezifikationskonzept zur formalen Beschreibung des Mindeststartintervalls (<code>minimum start interval</code>) und kein zwingender Bestandteil einer tatsächlichen Implementierung. RTE-Generatoren und OS-Scheduler müssen sicherstellen, dass Aktivierungsereignisse (<code>activate</code>) das konfigurierte Mindestintervall einhalten, bevor die Runnable erneut gestartet wird (<code>start</code>). Server-Runnables unterliegen gesonderten Ausführungsregeln und sind von dieser Zustandsmaschine ausgenommen.</p>"}], "trans": [{"from": "FIG-9c9ae067325cbdcb", "to": "FIG-f3c0d3883ed626c1", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
